import ctypes
import json

class GSLFunction(ctypes.Structure):
    _fields_ = [("f", ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)),]

class CQuadWorkspace(ctypes.Structure):
    pass

gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
gsl.gsl_integration_cquad.argtypes = [
    GSLFunction,
    ctypes.c_double,
    ctypes.c_double,
    ctypes.c_double,
    ctypes.c_double,
    ctypes.c_size_t,
    ctypes.POINTER(CQuadWorkspace),
]
gsl.gsl_integration_cquad.restype = ctypes.c_int

def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    try:
        gsl_func = GSLFunction(func)
        workspace = CQuadWorkspace()
        status = gsl.gsl_integration_cquad(
            gsl_func, a, b, epsabs, epsrel, workspace_size, ctypes.byref(workspace)
        )
        if status != 0:
            raise RuntimeError(f"Error in integration: {status}")
        return {
            "Candidate_solution": json.dumps(
                f"Integral = {workspace.result}\n"
                f"Absolute error = {workspace.abserr}\n"
                f"Function evaluations = {workspace.neval}"
            )
        }
    except Exception as e:
        return {"Candidate_solution": json.dumps(f"Error: {e}")}

