def configure_gsl_stats_median(gsl):
    gsl.gsl_stats_median_from_sorted_data.argtypes = [
        ctypes.POINTER(ctypes.c_double),
        ctypes.c_int
    ]
    gsl.gsl_stats_median_from_sorted_data.restype = ctypes.c_double

def compute_median(sorted_data):
    gsl = load_gsl_libraries()
    configure_gsl_stats_median(gsl)

