# GSL Matrix class
class GSLMatrix:
    def __init__(self, rows, cols):
        self.matrix = gsl.gsl_matrix_alloc(rows, cols)

    def free(self):
        gsl.gsl_matrix_free(self.matrix)

    def numpy_to_gsl(self, np_array):
        np.copyto(gsl_matrix_to_numpy(self.matrix), np_array)

    def gsl_to_numpy(self):
        return gsl_matrix_to_numpy(self.matrix)

# GSL functions
def gsl_matrix_alloc(rows, cols):
    return GSLMatrix(rows, cols)

def gsl_matrix_free(matrix):
    matrix.free()

def numpy_to_gsl_matrix(np_array):
    matrix = gsl_matrix_alloc(np_array.shape[0], np_array.shape[1])
    matrix.numpy_to_gsl(np_array)
    return matrix

def gsl_matrix_to_numpy(gsl_matrix):
    return np.array(gsl.gsl_matrix_data(gsl_matrix))

def gsl_multifit_covar(jacobian, epsrel):
    cov = gsl_matrix_alloc(jacobian.shape[1], jacobian.shape[1])
    gsl.gsl_multifit_covar(jacobian.matrix, epsrel, cov.matrix)
    return cov

# Compute covariance matrix
def covariance_matrix(jacobian, epsrel, dimensions):
    if dimensions != jacobian.shape[1]:
        raise ValueError("Invalid dimensions.")

    cov = gsl_multifit_covar(jacobian, epsrel)
    return cov.gsl_to_numpy()

