class gsl_permutation:
    def __init__(self, perm):
        self.p = gsl.gsl_permutation_alloc()
        gsl.gsl_permutation_init(self.p)
        for i in perm:
            gsl.gsl_permutation_set(self.p, i)

class gsl_vector:
    def __init__(self, vec):
        self.v = gsl.gsl_vector_alloc()
        for i in vec:
            gsl.gsl_vector_push_back(self.v, i)

def permute_vector(perm, vec):
    if len(perm) != len(vec):
        raise ValueError("Permutation and vector lengths must be equal.")

    p = gsl_permutation(perm)
    v = gsl_vector(vec)

    gsl.permute_vector(p.p, v.v)

    result = []
    for i in range(gsl.gsl_vector_size(v.v)):
        result.append(gsl.gsl_vector_get(v.v, i))

    gsl.gsl_permutation_free(p.p)
    gsl.gsl_vector_free(v.v)

    return result

