    ]

def integrate(function, a, b, epsabs, epsrel):
    gsl.gsl_integration_qng.restype = ctypes.c_double
    gsl.gsl_integration_qng.argtypes = [
        ctypes.POINTER(GSLFunction),
        ctypes.c_double,
        ctypes.c_double,
        ctypes.c_double,
        ctypes.c_double,
        ctypes.POINTER(ctypes.c_double),
        ctypes.POINTER(ctypes.c_ulong),
    ]

    gsl_function = GSLFunction(f=function)
    result = ctypes.c_double()
    neval = ctypes.c_ulong()

    gsl.gsl_integration_qng(
        ctypes.byref(gsl_function), a, b, epsabs, epsrel, ctypes.byref(result), ctypes.byref(neval)
    )

    return {"integral": result.value, "error": abs(result.value), "evaluations": neval.value}

