# Define the GSL combination class
class gsl_combination(ctypes.Structure):
    pass

# Define the function to get the next combination
def next_combination(current_combination, n):
    combination = gsl_combination()
    combination.n = n
    combination.k = len(current_combination)
    for i, value in enumerate(current_combination):
        combination.elements[i] = value

    gsl.gsl_combination_next(ctypes.byref(combination))

    if combination.k == 0:
        return None

    return tuple(combination.elements[:combination.k])

