class GSL_Histogram2D(ctypes.Structure):
    pass

# Define the create_histogram2d function
def create_histogram2d(nx, ny, xrange, yrange):
    # Validate input
    if not isinstance(nx, int) or nx <= 0:
        raise ValueError("Invalid nx value")
    if not isinstance(ny, int) or ny <= 0:
        raise ValueError("Invalid ny value")
    if not isinstance(xrange, list) or not isinstance(yrange, list):
        raise ValueError("Invalid xrange or yrange values")
    if len(xrange) != nx + 1 or len(yrange) != ny + 1:
        raise ValueError("Invalid xrange or yrange lengths")
    for i in range(1, len(xrange)):
        if xrange[i] <= xrange[i - 1]:
            raise ValueError("Invalid xrange values")
    for i in range(1, len(yrange)):
        if yrange[i] <= yrange[i - 1]:
            raise ValueError("Invalid yrange values")

    # Allocate memory for the gsl_histogram2d structure
    histogram = GSL_Histogram2D()

    # Call the gsl_histogram2d_calloc_range function
    result = gsl.gsl_histogram2d_calloc_range(
        ctypes.byref(histogram),
        nx, ny,
        (ctypes.c_double * len(xrange))(*xrange),
        (ctypes.c_double * len(yrange))(*yrange)
    )

    # Check for errors
    if result != 0:
        raise RuntimeError("Error creating histogram2d")

    # Return the gsl_histogram2d pointer
    return ctypes.pointer(histogram)

